INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (137, 'hotResultadoBase', 'Mount de Resultado Contabil em 1 ida (CRS,ANOS,DRE_CONFIG,CONTAS). Sem params.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''EMPRESA_ID'',t.EMPRESA_ID,''ATIVO'',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CRS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ANO'',x.ANO)) FROM (SELECT DISTINCT ANO FROM REALIZADO_CONTABIL) x),JSON_ARRAY()) AS ANOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''ORDEM'',t.ORDEM,''NOME_LINHA'',t.NOME_LINHA,''TIPO'',t.TIPO,''PREFIXO_CONTA'',t.PREFIXO_CONTA,''SINAL'',t.SINAL,''LINHA_PAI_ID'',t.LINHA_PAI_ID,''IS_SUBTOTAL'',t.IS_SUBTOTAL)) FROM DRE_CONFIG t WHERE 1=1),JSON_ARRAY()) AS DRE_CONFIG,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',c.ID,''CODIGO'',c.CODIGO,''NOME'',c.NOME,''TIPO'',c.TIPO)) FROM CONTA_CONTABIL c),JSON_ARRAY()) AS CONTAS', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
